#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
const int maxn = (int) 1e5 + 1;

#define int ll

int x, y, n;
double res = 1e9;
int p1, p2;
int lca(int a, int b){
    return a * b / __gcd(a, b);
}


main(){
    cin >> x >> y >> n;
    if(y <= n){
        while(__gcd(x, y) > 1){
            int h = __gcd(x, y);
            x /= h;
            y /= h;
        }
        cout << x << "/" << y;
        return 0;
    }
    for(int i = 1; i <= n; i++){
        int h = lca(i, y);
        int w = x * (h / y);
        if(res > (double)(w - ((w / (h / i)) * (h / i))) / (double)h){
            res = (double)(w - ((w / (h / i)) * (h / i))) / (double)h;
            p1 = (w / (h / i));
            p2 = i;
        }
        if(res > (double)abs(w - (((w + (h / i) - 1) / (h /i)) * (h /i))) / (double)h){
            res = (double)abs(w - (((w + (h /i) - 1) / (h /i)) * (h /i))) / (double)h;
            p1 = ((w + (h /i) - 1) / (h /i));
            p2 = i;
        }
    }
    int h = __gcd(p1, p2);
    p1 /= h;
    p2 /= h;
    cout << p1 << "/" << p2;
}

